import React from 'react';
import './footer.css';
import { FaFacebook, FaGoogle, FaYelp, FaPhoneAlt, FaEnvelope } from 'react-icons/fa';
import { BUSINESS, FOOTER, SERVICES, NAV } from '../../content';
import logo from '../../images/logo.jpg';
const Footer: React.FC = () => {
  const currentYear = new Date().getFullYear();
  // Support both NAV.mainLinks and a fallback
  const quickLinks = NAV.mainLinks || [];
  // Slice services based on footer config
  const footerServices = SERVICES.slice(0, FOOTER.servicesColumnCount || 5);

  return (
    <footer className="footer">
      <div className="footer-container">
        <div className="footer-grid">
          {/* Column 1: Logo & Description */}
          <div className="footer-col">
            <div className="footer-logo">
              <img src={logo} alt={BUSINESS.name} className="footer-logo-img" />
            </div>
            <p className="footer-description">
              {BUSINESS.description || FOOTER.description}
            </p>
          </div>

          {/* Column 2: Quick Links */}
          <div className="footer-col">
            <h3 className="footer-title">{FOOTER.quickLinksTitle}</h3>
            <ul className="footer-links">
              {quickLinks.map((link: any, index: number) => (
                <li key={index}><a href={link.href}>{link.name}</a></li>
              ))}
            </ul>
          </div>

          {/* Column 3: Services */}
          <div className="footer-col">
            <h3 className="footer-title">{FOOTER.servicesTitle}</h3>
            <ul className="footer-links">
              {footerServices.map((service: any, index: number) => (
                <li key={index}><a href={`/${service.slug}`}>{service.title}</a></li>
              ))}
            </ul>
          </div>

          {/* Column 4: Social & BBB */}
          <div className="footer-col">
            <h3 className="footer-title">{FOOTER.connectTitle}</h3>
            <div className="social-links">
              {FOOTER.social.map((item: any, index: number) => (
                <a key={index} href={item.url} target="_blank" rel="noopener noreferrer" className="social-link">
                  {item.platform === 'Facebook' ? <FaFacebook /> : item.platform === 'Yelp' ? <FaYelp /> : <FaGoogle />} {item.name}
                </a>
              ))}
            </div>
            {FOOTER.bbb.enabled && (
              <div className="bbb-badge">
                <a href={FOOTER.bbb.url} target="_blank" rel="noopener noreferrer">
                  <img src={FOOTER.bbb.image} alt="BBB Accredited Business" />
                  <span>{FOOTER.bbb.text}</span>
                </a>
              </div>
            )}
          </div>
        </div>

        <div className="footer-bottom">
          <p>&copy; {currentYear} {BUSINESS.name}. All rights reserved. | Created by <a target="_blank" rel="noopener noreferrer" className='domain' href={BUSINESS.creatorUrl}>{BUSINESS.creatorName}</a></p>
          <div className="footer-contact">
            <a href={BUSINESS.phoneHref}><FaPhoneAlt /> {BUSINESS.phone}</a>
            <a href={BUSINESS.emailHref}><FaEnvelope /> {BUSINESS.email}</a>
          </div>
        </div>
      </div>
    </footer>
  );
};

export default Footer;

